<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/ecosystem.php';
require_once __DIR__ . '/../config/bootstrap.php';
$pdo = beyond_db();

require_once __DIR__ . '/includes/verse-of-day.php';
require_once __DIR__ . '/includes/web-app.php';
require_once __DIR__ . '/includes/sacred-text.php';
$faithTradition = dailybreath_faith_tradition((string)($_GET['faith'] ?? $_COOKIE['dailybreath_faith'] ?? 'bible'));
setcookie('dailybreath_faith', $faithTradition, ['expires'=>time()+31536000,'path'=>'/dailybreath/','samesite'=>'Lax']);
$faithLabel = dailybreath_tradition_label($faithTradition);
$dailyVerse = dailybreath_interfaith_verse_of_day($pdo, $faithTradition, (string)($_SESSION['locale'] ?? 'en'));
$dailyTitle = $dailyVerse['text'];
$dailyBody = $dailyVerse['reference'];
$dailyDate = dailybreath_web_date();
$dailyScriptureUrl = dailybreath_scripture_url($dailyVerse);
$weekStartDate = date('Y-m-d', strtotime('monday this week'));
$weekEndDate = date('Y-m-d', strtotime($weekStartDate . ' +6 days'));
$weeklyVerse = dailybreath_interfaith_verse_of_day($pdo, $faithTradition, (string)($_SESSION['locale'] ?? 'en'), $weekStartDate);
$weeklyScriptureUrl = dailybreath_scripture_url($weeklyVerse);
$devotional = null;
try {
    $query = $pdo->prepare('SELECT title,excerpt,scripture_reference,duration_minutes FROM devotionals WHERE is_published=1 AND locale=? AND publish_date>=? AND publish_date<=? ORDER BY publish_date,id LIMIT 1');
    $query->execute([$_SESSION['locale'] ?? 'en', $weekStartDate, $weekEndDate]);
    $devotional = $query->fetch(PDO::FETCH_ASSOC) ?: null;
} catch (Throwable $exception) {}
$devotional = $devotional ?: dailybreath_recovery_devotional_for_date($weekStartDate, false)
    ?: dailybreath_recovery_devotional_for_date($weekStartDate)
    ?: ['title'=>'Walk in Quiet Confidence','excerpt'=>'Make room for stillness and remember that God is present before your next step.','scripture_reference'=>'Psalm 46:10','duration_minutes'=>5];
$reflectionLabel = "Weekly devotional";
$reflectionLink = 'devotionals.php';
$reflectionAction = 'Read devotional';
if ($faithTradition === 'torah') {
    $reflectionLabel = "Weekly Jewish reflection";
    $reflectionLink = $weeklyScriptureUrl;
    $reflectionAction = 'Read in Tanakh';
    $devotional = [
        'title'=>'Pause with This Week’s Tanakh Passage',
        'excerpt'=>'Read the passage slowly, notice the word or phrase that stays with you, and carry it into one faithful action this week.',
        'scripture_reference'=>$weeklyVerse['reference'],
        'duration_minutes'=>3,
    ];
} elseif ($faithTradition === 'quran') {
    $reflectionLabel = "Weekly Quran reflection";
    $reflectionLink = $weeklyScriptureUrl;
    $reflectionAction = 'Read in Quran';
    $devotional = [
        'title'=>'Pause with This Week’s Ayah',
        'excerpt'=>'Read the ayah with attention, reflect on its guidance, and carry one sincere response into this week.',
        'scripture_reference'=>$weeklyVerse['reference'],
        'duration_minutes'=>3,
    ];
}

$name = 'Friend';
$jaguarGuide = $faithTradition === 'quran' ? 'Moe' : ($faithTradition === 'torah' ? 'Dovi' : 'Chris');
$jaguarGuideKey = strtolower($jaguarGuide);
$jaguarCsrf = csrf_token();
$jaguarNonceSecret = trim((string) (getenv('JAGUAR_NONCE_SECRET') ?: beyond_config('security.jaguar_nonce_secret', beyond_config('security.jwt_secret', ''))));
$jaguarNonceIssuedAt = time();
$jaguarNonce = bin2hex(random_bytes(24));
$jaguarNonceSignature = $jaguarNonceSecret !== '' ? hash_hmac('sha256', $jaguarNonce . ':' . $jaguarNonceIssuedAt, $jaguarNonceSecret) : '';
$_SESSION['jaguar_nonce'] = ['value' => $jaguarNonce, 'issued_at' => $jaguarNonceIssuedAt, 'used' => false];
?>
