<script>(()=>{const panel=document.getElementById('home-chat'),open=document.getElementById('home-chat-open'),close=document.getElementById('home-chat-close'),form=document.getElementById('home-chat-form'),input=document.getElementById('home-chat-input'),messages=document.getElementById('home-chat-messages'),locale=<?= json_encode((string)($_SESSION['locale'] ?? 'en')) ?>;let history=[],nonce=<?= json_encode($jaguarNonce) ?>,issuedAt=<?= json_encode($jaguarNonceIssuedAt) ?>,signature=<?= json_encode($jaguarNonceSignature) ?>;const add=(role,text)=>{const item=document.createElement('p');item.className='home-chat-message '+role;item.textContent=text;messages.append(item);messages.scrollTop=messages.scrollHeight;return item};open.onclick=()=>{panel.hidden=false;input.focus()};close.onclick=()=>{panel.hidden=true};panel.onclick=event=>{if(event.target===panel)panel.hidden=true};form.onsubmit=async event=>{event.preventDefault();const text=input.value.trim();if(!text)return;input.value='';history.push({role:'user',content:text});add('user',text);const pending=add('assistant','<?= e($jaguarGuide) ?> is thinking…');try{const response=await fetch('api/jaguar-chat.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?= json_encode($jaguarCsrf) ?>},body:JSON.stringify({mode:'core',language:locale,guide:<?= json_encode($jaguarGuideKey) ?>,messages:history,nonce,nonce_issued_at:issuedAt,nonce_signature:signature})});const nextNonce=response.headers.get('X-Jaguar-Nonce'),nextIssuedAt=response.headers.get('X-Jaguar-Nonce-Issued-At'),nextSignature=response.headers.get('X-Jaguar-Nonce-Signature');if(nextNonce&&nextIssuedAt&&nextSignature){nonce=nextNonce;issuedAt=Number(nextIssuedAt);signature=nextSignature}const data=await response.json();if(!response.ok)throw new Error(data.error||'Daily Breath chat is unavailable.');pending.textContent=data.message;history.push({role:'assistant',content:data.message})}catch(error){pending.textContent=error instanceof Error?error.message:'Daily Breath chat is unavailable.'}}})();</script>
<script>(()=>{const splash=document.getElementById('splash'),welcome=document.getElementById('welcome-step'),tradition=document.getElementById('tradition-step'),chosen=localStorage.getItem('dailybreath.tradition');if(sessionStorage.getItem('dailybreath-entered')==='1'&&chosen)splash.classList.add('hidden');document.getElementById('enter').onclick=()=>{sessionStorage.setItem('dailybreath-entered','1');if(localStorage.getItem('dailybreath.tradition'))splash.classList.add('hidden');else{welcome.hidden=true;tradition.hidden=false}};document.querySelectorAll('[data-tradition]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.tradition;localStorage.setItem('dailybreath.tradition',value);window.location.href='?faith='+encodeURIComponent(value)+'&source=onboarding'}));})();</script>
